{
  "findings": [
    {
      "check_id": "CKV_AZURE_221",
      "title": "Function App public network access is enabled",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "MEDIUM",
      "explanation": "The Function App does not disable public network access, leaving its endpoint reachable from public networks by default."
    },
    {
      "check_id": "CKV_AZURE_70",
      "title": "Function App does not enforce HTTPS",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "MEDIUM",
      "explanation": "The Function App does not set https_only, so unencrypted HTTP requests may be accepted."
    },
    {
      "check_id": "CKV_AZURE_56",
      "title": "Function App authentication is not enabled",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "MEDIUM",
      "explanation": "No authentication settings are configured, so the platform does not require authenticated requests before invoking the application."
    },
    {
      "check_id": "CKV_AZURE_67",
      "title": "Function App does not enable HTTP/2",
      "resource": "azurerm_linux_function_app.alert_function",
      "severity": "MEDIUM",
      "explanation": "The site configuration does not enable HTTP/2, so the Function App may use an older HTTP protocol version."
    }
  ],
  "patched_code": "resource \"azurerm_linux_function_app\" \"alert_function\" {\n  name                          = \"smart-manufacturing-iot-monitoring-platform-function-app-alerts\"\n  resource_group_name           = azurerm_resource_group.smart_manufacturing.name\n  location                      = azurerm_resource_group.smart_manufacturing.location\n  service_plan_id               = azurerm_service_plan.dashboard_plan.id\n  storage_account_name          = azurerm_storage_account.function_storage.name\n  storage_account_access_key    = azurerm_storage_account.function_storage.primary_access_key\n  https_only                    = true\n  public_network_access_enabled = false\n\n  site_config {\n    http2_enabled = true\n\n    application_stack {\n      node_version = \"18\"\n    }\n  }\n\n  auth_settings_v2 {\n    auth_enabled           = true\n    require_authentication = true\n    require_https          = true\n    unauthenticated_action = \"Return401\"\n  }\n\n  app_settings = {\n    \"FUNCTIONS_WORKER_RUNTIME\" = \"node\"\n  }\n}\n",
  "fix_summary": "Disabled public network access, enforced HTTPS, and enabled HTTP/2. Added platform authentication settings that require authentication and reject unauthenticated requests."
}
